namespace StockManager.Report
{
    public partial class frmBaoCaoHopDong : FormBase, IForm
    {
        public const string PERMISSION_VIEW = "frmBaoCaoHopDong_View";
        public const string PERMISSION_EDIT = "frmBaoCaoHopDong_Edit";
        private const string STORE_NAME = "SMS_OutputOrder_BaoCaoHopDong";
        private const string GRID_QUERY_NAME = "SMS_OutputOrder_BaoCaoHopDong";

        DataTable dtbData = null;
        private bool bolIsRefresh = false;

        #region IForm Members

        private static frmBaoCaoHopDong _instance = null;

        public static frmBaoCaoHopDong Instance
        {
            get
            {
                if (_instance == null)
                    _instance = new frmBaoCaoHopDong();
                return _instance;
            }
        }

        public void Run(bool isShowDialog)
        {
            FormManager.Run(Instance, isShowDialog);
        }

        #endregion

        public frmBaoCaoHopDong()
        {
            InitializeComponent();
        }

        #region Support Functions

        private void CheckPermission()
        {
            uOffice.OfficeFilter = UserSession.GetOfficeFilter(PERMISSION_VIEW);
        }

        private void LoadReferenceData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadReferenceData));
            else
            {
                if (bolIsRefresh)
                    uOffice.RefrehData();
                else
                    uOffice.InitData();
            }
        }

        private void LoadData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadData));
            else
            {
                dtbData = null;
                SMS_OutputOrder obj = new SMS_OutputOrder();
                dtbData = obj.GetDataTable(STORE_NAME,
                        "@OfficeID", uOffice.EditValue,
                        "@FromDate", dtmFrom.EditValueDate,
                        "@ToDate", dtmTo.EditValueDate);

                if (dtbData != null)
                {
                    if (dtbData.Rows.Count == 0)
                    {
                        gcData.DataSource = null;
                        MessageManager.Warning("Không có dữ liệu!");
                        bolIsRefresh = false;
                        return;
                    }

                    SystemService.SYS_GridColumnService.InitGridColumn(gvData, GRID_QUERY_NAME, bolIsRefresh);

                    if (dtbData.Columns.Contains("PartnerName"))
                        dtbData.DefaultView.Sort = "PartnerName ASC, OutputOrderDate ASC, OutputOrderCode ASC";

                    gcData.DataSource = dtbData;
                    ModifyGrid();
                    ApplyPartnerGrouping();
                    gvData.ExpandAllGroups();

                    mnuItemExportExcel.Enabled = true;
                    bolIsRefresh = false;
                }
                else
                {
                    ErrorManager.Error("Việc lấy thông tin bị lỗi!");
                }
            }
        }

        private void ApplyPartnerGrouping()
        {
            BandedGridColumn colGroup = gvData.Columns.ColumnByFieldName("PartnerName") as BandedGridColumn;
            if (colGroup == null)
                return;

            gvData.Appearance.GroupRow.BackColor = Color.FromArgb(146, 208, 80);
            gvData.Appearance.GroupRow.ForeColor = Color.FromArgb(0, 70, 0);
            gvData.Appearance.GroupRow.Font = new Font("Tahoma", 9, FontStyle.Bold);
            gvData.Appearance.GroupRow.Options.UseBackColor = true;
            gvData.Appearance.GroupRow.Options.UseForeColor = true;
            gvData.Appearance.GroupRow.Options.UseFont = true;

            gvData.OptionsView.ShowGroupedColumns = false;
            gvData.OptionsView.ShowGroupPanel = false;
            gvData.GroupFormat = "[#image]{1} ({2} dòng)";

            gvData.ClearGrouping();
            colGroup.GroupIndex = 0;
            colGroup.SortOrder = DevExpress.Data.ColumnSortOrder.Ascending;

            BandedGridColumn colPartnerCode = gvData.Columns.ColumnByFieldName("PartnerCode") as BandedGridColumn;
            if (colPartnerCode != null)
                colPartnerCode.Visible = false;

            BandedGridColumn colThanhTien = gvData.Columns.ColumnByFieldName("ThanhTien") as BandedGridColumn;
            if (colThanhTien != null)
            {
                gvData.GroupSummary.Clear();
                gvData.GroupSummary.Add(DevExpress.Data.SummaryItemType.Sum, colThanhTien.FieldName, colThanhTien, "{0:#,##0}");
            }

            BandedGridColumn colGiaTriHopDong = gvData.Columns.ColumnByFieldName("GiaTriHopDong") as BandedGridColumn;
            if (colGiaTriHopDong != null)
            {
                colGiaTriHopDong.AppearanceCell.BackColor = Color.LightYellow;
                colGiaTriHopDong.AppearanceCell.Font = new Font(colGiaTriHopDong.AppearanceCell.Font, FontStyle.Bold);
            }

            BandedGridColumn colGiaTriDaThucHien = gvData.Columns.ColumnByFieldName("GiaTriDaThucHien") as BandedGridColumn;
            if (colGiaTriDaThucHien != null)
            {
                colGiaTriDaThucHien.AppearanceCell.BackColor = Color.LightGreen;
            }

            BandedGridColumn colConLai = gvData.Columns.ColumnByFieldName("ConLai") as BandedGridColumn;
            if (colConLai != null)
            {
                colConLai.AppearanceCell.BackColor = Color.LightBlue;
                colConLai.AppearanceCell.Font = new Font(colConLai.AppearanceCell.Font, FontStyle.Bold);
            }

            gvData.CustomDrawGroupRow -= gvData_CustomDrawGroupRow;
            gvData.CustomDrawGroupRow += gvData_CustomDrawGroupRow;
        }

        private void ModifyGrid()
        {
            BandedGridColumn colOutputOrderID = gvData.Columns.ColumnByFieldName("OutputOrderID") as BandedGridColumn;
            if (colOutputOrderID != null)
                colOutputOrderID.Visible = false;

            BandedGridColumn colPartnerID = gvData.Columns.ColumnByFieldName("PartnerID") as BandedGridColumn;
            if (colPartnerID != null)
                colPartnerID.Visible = false;

            BandedGridColumn colItemID = gvData.Columns.ColumnByFieldName("ItemID") as BandedGridColumn;
            if (colItemID != null)
                colItemID.Visible = false;
        }

        #endregion

        #region Form Actions

        static bool bolIsLoaded = false;
        private void frmBaoCaoHopDong_Load(object sender, EventArgs e)
        {
            if (!bolIsLoaded)
            {
                DateTime dtm = DateTime.Now;
                dtmFrom.EditValue = new DateTime(dtm.Year, 1, 1);
                dtmTo.EditValue = new DateTime(dtm.Year, 12, 31);

                SetToolTip();
                CheckPermission();
                new Thread(LoadReferenceData).Start();
                bolIsLoaded = true;
            }
        }

        private void btnClose_Click(object sender, EventArgs e)
        {
            this.Close();
        }

        private void frmBaoCaoHopDong_KeyDown(object sender, KeyEventArgs e)
        {
            switch (e.KeyData)
            {
                case Keys.F1:
                    this.ShowToolTip();
                    break;

                case Keys.Escape:
                    btnClose_Click(sender, null);
                    break;
            }
        }

        private void gvData_CustomDrawGroupRow(object sender, DevExpress.XtraGrid.Views.Base.RowObjectCustomDrawEventArgs e)
        {
            GridGroupRowInfo info = e.Info as GridGroupRowInfo;
            if (info == null)
                return;

            object objValue = gvData.GetGroupRowValue(e.RowHandle);
            string strPartnerName = (objValue == null || objValue == DBNull.Value)
                ? "(Chưa phân loại)"
                : objValue.ToString();

            if (string.IsNullOrEmpty(strPartnerName))
                strPartnerName = "(Chưa phân loại)";

            int intChildCount = gvData.GetChildRowCount(e.RowHandle);
            info.GroupText = String.Format("{0}  ({1} dòng)", strPartnerName, intChildCount);
        }

        #endregion

        private void mnuItemRefresh_Click(object sender, EventArgs e)
        {
            bolIsRefresh = true;
            btnSearch_Click(null, null);
        }

        private void mnuItemExportExcel_Click(object sender, EventArgs e)
        {
            gvData.QuickExportToExcel();
        }

        private void btnSearch_Click(object sender, EventArgs e)
        {
            if (dtmFrom.EditValue == null)
            {
                MessageManager.Warning("Bạn phải chọn ngày bắt đầu!");
                dtmFrom.Focus();
                return;
            }
            if (dtmTo.EditValue == null)
            {
                MessageManager.Warning("Bạn phải chọn ngày kết thúc!");
                dtmTo.Focus();
                return;
            }

            gvData.SummaryCollection = "ThanhTien";

            new Thread(LoadData).Start();
        }
    }
}

